-- Achievement statistics are submitted only when a non-debug run is finalized.
-- Anonymous player IDs identify one browser profile, not a verified person.
begin;

create table public.phd_simulator_v2_achievement_catalog (
  id text primary key,
  eligible_role_ids text[] not null check (cardinality(eligible_role_ids) > 0)
);

-- BEGIN GENERATED ACHIEVEMENT CATALOG
-- 175 achievements, 18 roles; generated by scripts/sync-achievement-stat-catalog.mjs
-- END GENERATED ACHIEVEMENT CATALOG

create table public.phd_simulator_v2_achievement_runs (
  id uuid primary key,
  player_id uuid not null,
  role_id text not null,
  achievement_ids text[] not null,
  finalized_at timestamptz not null default now()
);
create index phd_simulator_v2_achievement_runs_role_player_idx
  on public.phd_simulator_v2_achievement_runs (role_id, player_id);

create table public.phd_simulator_v2_achievement_completions (
  player_id uuid not null,
  achievement_id text not null references public.phd_simulator_v2_achievement_catalog(id),
  role_id text not null,
  completed_at timestamptz not null default now(),
  primary key (player_id, achievement_id, role_id)
);
create index phd_simulator_v2_achievement_completions_achievement_player_idx
  on public.phd_simulator_v2_achievement_completions (achievement_id, player_id);

alter table public.phd_simulator_v2_achievement_catalog enable row level security;
alter table public.phd_simulator_v2_achievement_runs enable row level security;
alter table public.phd_simulator_v2_achievement_completions enable row level security;
revoke all on public.phd_simulator_v2_achievement_catalog,
  public.phd_simulator_v2_achievement_runs,
  public.phd_simulator_v2_achievement_completions from public, anon, authenticated;

create function public.record_phd_simulator_v2_achievement_run(
  p_player_id uuid, p_run_id uuid, p_role_id text, p_achievement_ids text[]
)
returns boolean
language plpgsql
security definer
set search_path = ''
as $$
declare
  normalized_ids text[];
  existing_run public.phd_simulator_v2_achievement_runs%rowtype;
  inserted_id uuid;
begin
  if p_player_id is null or p_run_id is null
    or p_player_id::text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or p_run_id::text !~ '^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    or p_role_id is null
    or not exists (select 1 from public.phd_simulator_v2_achievement_catalog c where p_role_id = any(c.eligible_role_ids))
    or p_achievement_ids is null
    or cardinality(p_achievement_ids) > 512
    or exists (select 1 from pg_catalog.unnest(p_achievement_ids) a(id) where a.id is null) then
    raise exception 'Invalid achievement run' using errcode = '22023';
  end if;

  select coalesce(pg_catalog.array_agg(a.id order by a.id), '{}'::text[])
    into normalized_ids from (select distinct pg_catalog.unnest(p_achievement_ids) as id) a;
  if exists (
    select 1 from pg_catalog.unnest(normalized_ids) a(id)
    where not exists (select 1 from public.phd_simulator_v2_achievement_catalog c
      where c.id = a.id and p_role_id = any(c.eligible_role_ids))
  ) then
    raise exception 'Unknown achievement or ineligible role' using errcode = '22023';
  end if;

    values (p_run_id, p_player_id, p_role_id, normalized_ids)
    on conflict (id) do nothing returning id into inserted_id;
  if inserted_id is null then
    select * into existing_run from public.phd_simulator_v2_achievement_runs where id = p_run_id for update;
    if existing_run.player_id is distinct from p_player_id
      or existing_run.role_id is distinct from p_role_id
      or existing_run.achievement_ids is distinct from normalized_ids then
      raise exception 'Finalized achievement run cannot be changed' using errcode = '22023';
    end if;
    return true;
  end if;

    select p_player_id, a.id, p_role_id from pg_catalog.unnest(normalized_ids) a(id)
    on conflict (player_id, achievement_id, role_id) do nothing;
  return true;
end;
$$;

create function public.get_phd_simulator_v2_achievement_stats()
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with player_roles as (
    select distinct player_id, role_id from public.phd_simulator_v2_achievement_runs
  ), eligible as (
    select c.id, count(distinct r.player_id) as players
    from public.phd_simulator_v2_achievement_catalog c
    left join player_roles r on r.role_id = any(c.eligible_role_ids)
    group by c.id
  ), achieved as (
    select a.achievement_id, count(distinct a.player_id) as players
    from public.phd_simulator_v2_achievement_completions a
    join public.phd_simulator_v2_achievement_catalog c on c.id = a.achievement_id
      and a.role_id = any(c.eligible_role_ids)
    group by a.achievement_id
  )
  select pg_catalog.jsonb_build_object('version', 1, 'achievements',
    coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
      'id', e.id, 'achievedPlayers', coalesce(a.players, 0), 'eligiblePlayers', e.players
    ) order by e.id), '[]'::jsonb))
  from eligible e left join achieved a on a.achievement_id = e.id;
$$;

revoke all on function public.record_phd_simulator_v2_achievement_run(uuid, uuid, text, text[])
  from public, anon, authenticated;
revoke all on function public.get_phd_simulator_v2_achievement_stats()
  from public, anon, authenticated;
grant execute on function public.record_phd_simulator_v2_achievement_run(uuid, uuid, text, text[])
  to anon, authenticated;
grant execute on function public.get_phd_simulator_v2_achievement_stats()
  to anon, authenticated;

notify pgrst, 'reload schema';
commit;
